final class ParamModel: Model {
    internal init(label: String, name: String, type: SwiftType, isGeneric: Bool, inInit: Bool, needsVarDecl: Bool, offset: Int64, length: Int64) {
        self.label = label
        self.name = name
        self.type = type
        self.isGeneric = isGeneric
        self.inInit = inInit
        self.needsVarDecl = needsVarDecl
        self.offset = offset
        self.length = length
    }

    let label: String
    let name: String
    let type: SwiftType
    let isGeneric: Bool
    let inInit: Bool
    let needsVarDecl: Bool
    let offset: Int64
    let length: Int64

    var modelType: ModelType {
        return .parameter
    }

    var fullName: String {
        return label + "_" + name
    }

    var underlyingName: String {
        return "_\(name)"
    }

    /// - Parameters:
    ///     - eraseType:
    ///         If other initializers in decl has same name as this param and type is different from each other,
    ///         please pass `True` to this parameter. Default value is `false`.
    ///
    /// ```
    ///     protocol A {
    ///         init(param: String)
    ///         init(param: any Sequence<Character>)
    ///     }
    ///     class B: A {
    ///         var param: Any! // NOTE: type erasing
    ///         init () {}
    ///         required init(param: String) {
    ///           self.param = param
    ///         }
    ///         required init(param: any Sequence<Character>) {
    ///             self.param = param
    ///         }
    ///     }
    /// ```
    func asInitVarDecl(eraseType: Bool) -> String? {
        if self.inInit, self.needsVarDecl {
            let type: SwiftType
            if eraseType {
                type = SwiftType.Any
            } else {
                type = self.type
            }
            return applyVarTemplate(type: type)
        }
        return nil
    }

    func render(
        context: RenderContext,
        arguments: GenerationArguments
    ) -> String? {
        return applyParamTemplate(name: name, label: label, type: type, inInit: inInit, isGeneric: isGeneric)
    }
}

extension [ParamModel] {
    func render(
        context: RenderContext,
        arguments: GenerationArguments
    ) -> String {
        return self.compactMap {
            $0.render(
                context: context,
                arguments: arguments
            )
        }.joined(separator: ", ")
    }
}

